(()=>{
const D=window.STORE_DATA,E=window.FAQEngine,app=document.querySelector('#app'),dialog=document.querySelector('#editor');
const storage='riwaq-faq-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(storage)||'{}')}catch{}
const seed=D.faqs.map(f=>({...f,status:'approved',category:/شحن|يصل/.test(f.question)?'الشحن والتوصيل':/إرجاع|استرجاع|ترجيع/.test(f.question)?'الإرجاع والاستبدال':'عام',source:'الأسئلة الموثقة · faqs / '+f.id}));let state={faqs:saved.faqs||seed,tab:'overview',filter:'all',search:'',category:'all',productSearch:'',activeCategory:'الكل',cart:0};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>new Intl.NumberFormat('ar-SA').format(n);const persist=()=>localStorage.setItem(storage,JSON.stringify({faqs:state.faqs}));const product=id=>D.products.find(p=>p.id===id);const url=p=>p.main_image||p.images?.[0]?.url||'';const listApproved=()=>state.faqs.filter(f=>f.status==='approved');
function toast(s){let t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
function nav(){let [page,param]=(location.hash.slice(1)||'/store').split('/').filter(Boolean);if(page==='dashboard')renderDashboard();else if(page==='product')renderProduct(param);else if(page==='faqs')renderFaqs();else renderStore();bindHeader()}function bindHeader(){let b=document.querySelector('.menu-btn');b?.addEventListener('click',()=>document.querySelector('.main-nav')?.classList.toggle('open'))}
function brand(){return `<a class="brand" href="#/store"><img src="assets/brand/logo.jpg" alt=""/><span><b>رِواق القهوة</b><small>قهوتك على رواق</small></span></a>`}
function header(mode='store'){return `<header class="topbar">${brand()}<nav class="main-nav"><a class="${mode==='store'?'selected':''}" href="#/store">المتجر</a><a class="${mode==='faqs'?'selected':''}" href="#/faqs">الأسئلة الشائعة</a><a class="${mode==='dashboard'?'selected':''}" href="#/dashboard">لوحة التاجر</a></nav><div class="top-actions"><span class="secure"><i></i> بيانات تدريبية</span><a class="icon-btn cart-btn" href="#/store" aria-label="السلة">♧ <sup>${fmt(state.cart)}</sup></a><button class="menu-btn" aria-label="القائمة">☰</button></div></header>`}
function footer(){return `<footer><div>${brand()}<p>اختيارات هادئة لتحضير قهوتك كما تحب.</p></div><div><b>روابط سريعة</b><a href="#/faqs">الأسئلة الشائعة</a><a href="#/dashboard">لوحة التاجر التجريبية</a></div><div class="footer-note">© 2026 رواق القهوة <span>متجر تجريبي ببيانات افتراضية</span></div></footer>`}
function productCard(p){let cat=D.categories.find(c=>c.id===p.category_id)?.name||'مختارات';return `<article class="product-card"><a href="#/product/${p.id}" class="product-img"><img src="${esc(url(p))}" alt="${esc(p.name)}" loading="lazy"><span>${esc(cat)}</span><button class="quick-add" data-cart="${p.id}" aria-label="أضف ${esc(p.name)} إلى السلة">+</button></a><div class="product-info"><a href="#/product/${p.id}" class="product-name">${esc(p.name)}</a><div class="card-bottom"><b>${fmt(p.price)} <small>ر.س</small></b><a href="#/product/${p.id}" aria-label="عرض التفاصيل">←</a></div></div></article>`}
function renderStore(){document.title='المتجر | رواق القهوة';app.innerHTML=header('store')+`<main><section class="hero"><div class="hero-copy"><span class="eyebrow">مساحة هادئة لعشاق القهوة</span><h1>قهوتك،<br><em>على رَواق.</em></h1><p>حبوب مختارة وأدوات تحضير تساعدك تصنع لحظتك المفضلة، بكل بساطة.</p><div class="hero-actions"><a class="btn primary" href="#products">اكتشف المنتجات <span>←</span></a><a class="text-link" href="#/faqs">عندك سؤال؟ <span>↗</span></a></div><div class="hero-trust"><span>✳ معلومات واضحة</span><span>✳ اختيارات مدروسة</span><span>✳ تفاصيل موثقة</span></div></div><div class="hero-art"><img src="assets/brand/hero.jpg" alt="أجواء تحضير القهوة في رواق القهوة"><div class="art-caption"><b>لحظتك تبدأ من هنا</b><span>تصفّح بهدوء، واختر ما يناسبك</span></div><div class="art-stamp">R<br><small>EST. 2024</small></div></div></section>
<section class="benefits"><div><span>01</span><b>معلومات موثقة</b><small>كل تفصيلة من بيانات المنتج</small></div><div><span>02</span><b>اختيار أسهل</b><small>اعرف ما يناسب طريقتك</small></div><div><span>03</span><b>أسئلة واضحة</b><small>إجابات قبل اتخاذ قرارك</small></div></section>
<section class="catalog section" id="products"><div class="section-head"><div><span class="eyebrow">تسوّق مجموعتنا</span><h2>اختيارات <em>رِواق</em></h2><p>أشياء بسيطة، تصنع فرقًا في فنجانك.</p></div><span class="result-count">${fmt(D.products.length)} منتج</span></div><div class="toolbar"><label class="search"><span>⌕</span><input id="product-search" placeholder="ابحث عن منتج أو نكهة..." value="${esc(state.productSearch)}"><kbd>⌘ K</kbd></label><div class="chips">${['الكل',...D.categories.map(c=>c.name)].map(c=>`<button class="chip ${state.activeCategory===c?'active':''}" data-category="${esc(c)}">${esc(c)}</button>`).join('')}</div></div><div class="product-grid" id="product-grid">${renderCards()}</div><div class="catalog-end"><span>نهاية المجموعة</span><i></i></div></section>
<section class="faq-callout"><div class="callout-icon">؟</div><div><span class="eyebrow">نحن هنا لمساعدتك</span><h2>ما زال عندك سؤال؟</h2><p>جمعنا لك الإجابات عن الشحن، المنتجات، وكل ما يهمك.</p></div><a class="btn light" href="#/faqs">تصفّح الأسئلة <span>←</span></a></section></main>`+footer();bindStore()}
function renderCards(){let q=E.normalize(state.productSearch);return D.products.filter(p=>(state.activeCategory==='الكل'||D.categories.find(c=>c.id===p.category_id)?.name===state.activeCategory)&&(!q||E.normalize(p.name+' '+p.description+' '+(p.tags||[]).join(' ')).includes(q))).map(productCard).join('')||'<div class="empty">ما لقينا منتجات تطابق بحثك.</div>'}
function bindStore(){document.querySelector('#product-search').addEventListener('input',e=>{state.productSearch=e.target.value;document.querySelector('#product-grid').innerHTML=renderCards();bindCards()});document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{state.activeCategory=b.dataset.category;document.querySelectorAll('[data-category]').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#product-grid').innerHTML=renderCards();bindCards()});bindCards()}
function bindCards(){document.querySelectorAll('[data-cart]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();state.cart++;let count=document.querySelector('.cart-btn sup');if(count)count.textContent=fmt(state.cart);toast('أُضيف المنتج إلى سلتك')})}
function faqCard(f){return `<details class="faq-item"><summary>${esc(f.question)}<span>＋</span></summary><div class="faq-answer">${esc(f.answer)}${f.product_id?`<a href="#/product/${f.product_id}">تفاصيل المنتج ←</a>`:''}</div></details>`}
function renderProduct(id){const p=product(id);if(!p){location.hash='#/store';return}document.title=p.name+' | رواق القهوة';let specs=p.specifications||[],variants=D.variants.filter(v=>v.product_id===id),chosen=variants[0]||null;let related=listApproved().filter(f=>f.product_id===id);app.innerHTML=header('store')+`<main class="detail-page"><div class="crumb"><a href="#/store">المتجر</a><span>／</span>${esc(p.name)}</div><section class="product-detail"><div class="detail-image"><img src="${esc(url(p))}" alt="${esc(p.name)}"><span>صورة توضيحية</span></div><div class="detail-copy"><span class="eyebrow">${esc(D.categories.find(c=>c.id===p.category_id)?.name||'مختارات رواق')}</span><h1>${esc(p.name)}</h1><p>${esc(p.description||p.short_description||'')}</p><div class="detail-price"><span id="detail-price-value">${fmt(chosen?.price??p.price)}</span> <small>ر.س</small> <span>شامل الضريبة</span></div>${variants.length>1?`<label class="variant-picker">اختر الخيار<select id="variant-select">${variants.map(v=>`<option value="${v.id}">${esc(Object.values(v.options||{}).join(' · ')||v.sku)} · ${fmt(v.price)} ر.س</option>`).join('')}</select></label>`:''}<button class="btn primary wide" data-cart="${p.id}">أضف إلى السلة <span>＋</span></button><div class="detail-note" id="detail-stock">✓ ${(chosen?.stock_quantity??p.stock_quantity)>0?'متوفر':'نفد المخزون'}</div><div class="detail-divider"></div><h3>عن المنتج</h3><div class="spec-grid">${specs.slice(0,8).map(s=>`<div><small>${esc(s.label_ar)}</small><b>${esc(Array.isArray(s.value)?s.value.join('، '):typeof s.value==='boolean'?(s.value?'نعم':'لا'):s.value)}</b></div>`).join('')}</div>${p.usage_instructions?.length?`<h3>طريقة الاستخدام</h3><ul class="soft-list">${p.usage_instructions.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}<h3>محتويات العبوة</h3><p class="included">${esc((p.included_items||[]).join('، ')||p.name)}</p></div></section><section class="detail-faq section"><div class="section-head"><div><span class="eyebrow">إجابات تساعدك تختار</span><h2>أسئلة عن المنتج</h2></div></div>${related.length?related.map(faqCard).join(''):`<div class="no-answer"><span>✳</span><div><b>نعمل على إضافة معلومات أكثر عن هذا المنتج</b><p>تواصل معنا وسنساعدك بالمعلومات المتوفرة لدينا.</p><a href="mailto:support@example.com">تواصل مع رواق ←</a></div></div>`}</section></main>`+footer();bindCards();document.querySelector('#variant-select')?.addEventListener('change',e=>{let v=variants.find(x=>x.id===e.target.value);if(v){document.querySelector('#detail-price-value').textContent=fmt(v.price);document.querySelector('#detail-stock').textContent='✓ '+(v.stock_quantity>0?'متوفر':'نفد المخزون')}})}
function renderFaqs(){document.title='الأسئلة الشائعة | رواق القهوة';let rows=listApproved(),cats=['الكل',...new Set(rows.map(f=>f.category||'عام'))];let q=E.normalize(state.search);rows=rows.filter(f=>(state.category==='الكل'||(f.category||'عام')===state.category)&&(!q||E.normalize(f.question+' '+f.answer).includes(q)));app.innerHTML=header('faqs')+`<main><section class="faq-hero"><span class="eyebrow">مركز المساعدة</span><h1>إجابات واضحة،<br><em>واختيار أهدأ.</em></h1><p>كل ما تحتاج معرفته عن منتجات رواق القهوة والطلبات.</p><label class="search faq-search"><span>⌕</span><input id="faq-search" placeholder="اكتب سؤالك هنا..." value="${esc(state.search)}"><kbd>↵</kbd></label></section><section class="faq-list section"><div class="chips">${cats.map(c=>`<button class="chip ${state.category===c?'active':''}" data-fcat="${esc(c)}">${esc(c)}</button>`).join('')}</div><div id="faq-results">${rows.length?rows.map(faqCard).join(''):'<div class="empty">ما لقينا إجابة مطابقة. تواصل معنا ونساعدك بكل سرور.<br><a href="mailto:support@example.com">support@example.com</a></div>'}</div><div class="no-answer"><span>✳</span><div><b>ما وجدت إجابة سؤالك؟</b><p>يسعد فريق رواق بمساعدتك.</p><a href="mailto:support@example.com">تواصل معنا ←</a></div></div></section></main>`+footer();const update=()=>{let list=listApproved().filter(f=>(state.category==='الكل'||(f.category||'عام')===state.category)&&(!E.normalize(state.search)||E.normalize(f.question+' '+f.answer).includes(E.normalize(state.search))));document.querySelector('#faq-results').innerHTML=list.length?list.map(faqCard).join(''):'<div class="empty">ما لقينا إجابة مطابقة. تواصل معنا ونساعدك بكل سرور.</div>'};document.querySelector('#faq-search').oninput=e=>{state.search=e.target.value;update()};document.querySelectorAll('[data-fcat]').forEach(b=>b.onclick=()=>{state.category=b.dataset.fcat;document.querySelectorAll('[data-fcat]').forEach(x=>x.classList.toggle('active',x===b));update()})}
function renderDashboard(){document.title='لوحة التاجر | رواق القهوة';let approved=listApproved().length,drafts=state.faqs.filter(f=>f.status==='draft').length,gaps=D.products.reduce((n,p)=>n+(p.unknown_fields||[]).length,0);app.innerHTML=header('dashboard')+`<main class="dashboard"><aside class="dash-side"><div class="dash-label">مساحة التاجر</div><a href="#/dashboard" class="dash-link active">▦ <span>نظرة عامة</span></a><button class="dash-link" data-tab="questions">✳ <span>صانع الأسئلة</span><b>${fmt(drafts)}</b></button><button class="dash-link" data-tab="gaps">◉ <span>معلومات ناقصة</span><b>${fmt(gaps)}</b></button><a class="dash-link" href="#/store">↗ <span>معاينة المتجر</span></a><div class="side-help"><span>✳</span><b>كل إجابة لها مصدر</b><p>راجع المصدر قبل اعتماد الإجابة ليشاهدها العميل.</p></div><div class="dash-user"><div class="avatar">ر</div><div><b>رواق القهوة</b><small>مساحة تجريبية</small></div><span>•••</span></div></aside><section class="dash-main"><div class="dash-top"><div><div class="crumb">لوحة التحكم <span>／</span> <b id="dash-breadcrumb">نظرة عامة</b></div><h1 id="dash-title">أهلًا بك في رِواق <span>✳</span></h1><p id="dash-subtitle">هذه لمحة عن متجرك والأسئلة التي تنتظر مراجعتك.</p></div><div class="dash-date">◷ <span>آخر تحديث: اليوم</span></div></div><div id="dash-content"></div></section></main>`+footer();document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;drawDashboard()});drawDashboard()}
function stats(){return `<div class="stats-grid"><article class="stat-card"><span>إجمالي المنتجات</span><b>${fmt(D.products.length)}</b><small><i class="green-dot"></i> في الكتالوج</small><span class="stat-icon">▧</span></article><article class="stat-card"><span>الطلبات التجريبية</span><b>${fmt(D.summary.orders)}</b><small>ضمن بيانات السيناريو</small><span class="stat-icon">⌑</span></article><article class="stat-card"><span>العملاء</span><b>${fmt(D.summary.customers)}</b><small>ملخص فقط، دون بيانات شخصية</small><span class="stat-icon">♙</span></article><article class="stat-card"><span>أسئلة معتمدة</span><b>${fmt(approvedCount())}</b><small><i class="gold-dot"></i> تظهر في المتجر</small><span class="stat-icon">✳</span></article></div>`}
function approvedCount(){return listApproved().length}
function drawDashboard(){let content=document.querySelector('#dash-content');if(!content)return;let title=state.tab==='questions'?'صانع الأسئلة الشائعة':state.tab==='gaps'?'معلومات تحتاج توضيحًا':'نظرة عامة';document.querySelector('#dash-title').innerHTML=state.tab==='overview'?'أهلًا بك في رِواق <span>✳</span>':title;document.querySelector('#dash-breadcrumb').textContent=title;document.querySelector('#dash-subtitle').textContent=state.tab==='overview'?'هذه لمحة عن متجرك والأسئلة التي تنتظر مراجعتك.':state.tab==='questions'?'استخرج اقتراحات من معلومات المتجر، وراجعها قبل ظهورها للعملاء.':'أكمل المعلومات الناقصة لتصبح الإجابات أوضح للعملاء.';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));if(state.tab==='overview'){content.innerHTML=stats()+`<div class="dash-columns"><section class="panel"><div class="panel-head"><div><span class="eyebrow">ابدأ من هنا</span><h2>حوّل الاستفسارات إلى إجابات</h2></div><span class="panel-mark">✳</span></div><p>أنشئ اقتراحات مبنية على معلومات منتجاتك وسياسات المتجر، ثم راجعها قبل نشرها.</p><button class="btn primary" data-generate>إنشاء اقتراحات الأسئلة <span>←</span></button><div class="process"><div><i>1</i><b>توليد</b><small>من بيانات موثقة</small></div><span>···</span><div><i>2</i><b>مراجعة</b><small>تعديل واعتماد</small></div><span>···</span><div><i>3</i><b>عرض</b><small>في صفحة المتجر</small></div></div></section><section class="panel pending"><div class="panel-head"><div><span class="eyebrow">تحتاج انتباهك</span><h2>مراجعة المحتوى</h2></div><a href="#" data-goto="questions">عرض الكل ←</a></div><div class="pending-line"><span class="pending-icon">✳</span><div><b>${fmt(state.faqs.filter(f=>f.status==='draft').length)} اقتراحًا بانتظار المراجعة</b><small>لا تظهر في واجهة العملاء حتى تعتمدها</small></div></div><div class="pending-line"><span class="pending-icon pale">◉</span><div><b>${fmt(D.products.reduce((n,p)=>n+(p.unknown_fields||[]).length,0))} معلومة غير موثقة</b><small>يمكنك استكمالها أو تركها دون إجابة</small></div></div></section></div><section class="panel recent"><div class="panel-head"><div><span class="eyebrow">نظرة سريعة</span><h2>آخر الأسئلة المعتمدة</h2></div><button class="subtle-btn" data-tab="questions">إدارة الأسئلة ←</button></div>${listApproved().slice(0,4).map(f=>`<div class="mini-row"><span class="check">✓</span><div><b>${esc(f.question)}</b><small>${esc(f.category||'المنتجات')}</small></div><span class="published">منشور</span></div>`).join('')||'<div class="empty">ما فيه أسئلة معتمدة. شغّل صانع الأسئلة للبدء.</div>'}</section>`}else if(state.tab==='questions')drawQuestions(content);else drawGaps(content);wireDashboard()}
function drawQuestions(content){content.innerHTML=`<section class="panel generator"><div class="panel-head"><div><span class="eyebrow">محتوى من بياناتك</span><h2>أنشئ اقتراحات جديدة</h2><p>نقرأ الأسئلة الحالية وبيانات المنتجات لصياغة اقتراحات تراجعها بنفسك.</p></div><span class="panel-mark">✳</span></div><div class="generator-controls"><label>نطاق التوليد<select id="generate-scope"><option value="all">المتجر وجميع المنتجات</option><option value="store">أسئلة المتجر العامة</option>${D.products.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select></label><button class="btn primary" data-generate>تشغيل صانع الأسئلة <span>✦</span></button></div><div class="source-note">ⓘ تُبنى الإجابات من البيانات المسجلة فقط. المعلومات غير الموثقة تظهر دون إجابة لتكملها بنفسك.</div></section><section class="panel questions-panel"><div class="panel-head"><div><span class="eyebrow">مكتبة الأسئلة</span><h2>الأسئلة والإجابات</h2></div><button class="export-btn" data-export>↓ تصدير المعتمد</button></div><div class="question-filters"><div class="chips"><button class="chip ${state.filter==='all'?'active':''}" data-filter="all">الكل <b>${fmt(state.faqs.length)}</b></button><button class="chip ${state.filter==='draft'?'active':''}" data-filter="draft">مسودة <b>${fmt(state.faqs.filter(f=>f.status==='draft').length)}</b></button><button class="chip ${state.filter==='approved'?'active':''}" data-filter="approved">معتمد <b>${fmt(approvedCount())}</b></button><button class="chip ${state.filter==='hidden'?'active':''}" data-filter="hidden">مخفي <b>${fmt(state.faqs.filter(f=>f.status==='hidden').length)}</b></button></div><label class="search compact"><span>⌕</span><input id="dash-search" placeholder="ابحث في الأسئلة..." value="${esc(state.search)}"></label></div><div id="question-list">${questionRows()}</div></section>`}
function questionRows(){let q=E.normalize(state.search),rows=state.faqs.filter(f=>(state.filter==='all'||f.status===state.filter)&&(!q||E.normalize(f.question+' '+f.answer).includes(q)));if(!rows.length)return '<div class="empty">لا توجد أسئلة هنا بعد.</div>';return rows.map(f=>`<article class="question-row"><div class="q-status ${f.status}">${f.status==='approved'?'✓':f.status==='hidden'?'⊘':'✳'}</div><div class="q-content"><div class="q-meta"><span>${esc(f.category||'عام')}</span><span>·</span><span>${f.product_id?esc(product(f.product_id)?.name||'منتج'):'المتجر'}</span>${f.count?`<span class="asked-count">↗ ورد ${fmt(f.count)} مرة</span>`:''}</div><h3>${esc(f.question)}</h3><p>${f.answer?esc(f.answer):'<i>المعلومة غير متوفرة — أضف إجابة موثقة قبل الاعتماد.</i>'}</p><small class="source-label">المصدر: ${esc(f.source||'إضافة التاجر')}</small></div><div class="q-actions"><span class="status-label ${f.status}">${f.status==='approved'?'معتمد':f.status==='hidden'?'مخفي':'بانتظارك'}</span><button data-edit="${esc(f.id)}">مراجعة ←</button></div></article>`).join('')}
function gapsList(){return D.products.flatMap(p=>(p.unknown_fields||[]).map((field,i)=>({p,field,i}))).map(({p,field,i})=>`<article class="gap-row"><span>◉</span><div><b>${esc(p.name)}</b><p>معلومة تحتاج توضيحًا: ${esc(Array.isArray(field)?field.join('، '):field)}</p><small>لا توجد إجابة موثقة في بيانات المنتج.</small></div><button data-gap="${p.id}:${i}">أضف معلومة</button></article>`).join('')||'<div class="empty">لا توجد معلومات ناقصة.</div>'}
function drawGaps(content){content.innerHTML=`<section class="panel gaps-panel"><div class="panel-head"><div><span class="eyebrow">وضوح أكثر للعملاء</span><h2>معلومات غير موثقة</h2><p>لن ننشئ إجابات عن هذه المعلومات تلقائيًا. يمكنك إضافة ما تعرفه بصفتك التاجر.</p></div><span class="panel-mark">◉</span></div><div class="source-note">معلومات التاجر تميّز عن بيانات الكتالوج، ويمكن تعديلها أو حذفها لاحقًا.</div>${gapsList()}</section>`}
function wireDashboard(){document.querySelectorAll('[data-generate]').forEach(b=>b.onclick=()=>{let scope=document.querySelector('#generate-scope')?.value||'all',incoming=E.generate(D,scope);state.faqs=E.merge(state.faqs,incoming);persist();state.tab='questions';state.filter='draft';state.search='';drawDashboard();toast('تم تحديث الاقتراحات دون تكرار الأسئلة الموجودة')});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;drawDashboard()});document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=e=>{e.preventDefault();state.tab=b.dataset.goto;drawDashboard()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;drawDashboard()});document.querySelector('#dash-search')?.addEventListener('input',e=>{state.search=e.target.value;let el=document.querySelector('#question-list');if(el)el.innerHTML=questionRows();wireActions()});wireActions()}
function wireActions(){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>editFaq(b.dataset.edit));document.querySelectorAll('[data-export]').forEach(b=>b.onclick=exportFaqs);document.querySelectorAll('[data-gap]').forEach(b=>b.onclick=()=>editGap(b.dataset.gap))}
function editFaq(id){const f=state.faqs.find(x=>x.id===id);if(!f)return;dialog.innerHTML=`<form method="dialog" class="edit-form" id="edit-form"><button class="dialog-close" value="cancel" aria-label="إغلاق">×</button><span class="eyebrow">مراجعة المحتوى</span><h2>راجع الإجابة قبل ظهورها</h2><label>السؤال<input name="question" required value="${esc(f.question)}"></label><label>الإجابة<textarea name="answer" rows="5" placeholder="أكمل الإجابة من معلومة موثوقة" required>${esc(f.answer)}</textarea></label><div class="source-note">المصدر: ${esc(f.source)}${f.count?` · ورد هذا الموضوع ${fmt(f.count)} مرة`:''}</div><div class="modal-actions"><button type="button" class="subtle-btn" id="save-draft">حفظ التعديل</button>${f.status==='approved'?'<button type="button" class="danger-btn" id="hide-faq">إخفاء من المتجر</button>':'<button type="button" class="btn primary" id="approve-faq">اعتماد وإظهار</button>'}</div></form>`;dialog.showModal();document.querySelector('#save-draft').onclick=()=>{const form=new FormData(document.querySelector('#edit-form'));Object.assign(f,{question:form.get('question'),answer:form.get('answer'),merchant:true});persist();dialog.close();drawDashboard();toast('حُفظ التعديل')};document.querySelector('#approve-faq')?.addEventListener('click',()=>{let data=new FormData(document.querySelector('#edit-form'));f.question=data.get('question');f.answer=data.get('answer');f.merchant=true;try{Object.assign(f,E.approve(f))}catch(e){toast(e.message);return}persist();dialog.close();drawDashboard();toast('ظهر السؤال في صفحة العملاء')});document.querySelector('#hide-faq')?.addEventListener('click',()=>{f.status='hidden';persist();dialog.close();drawDashboard();toast('أُخفي السؤال من واجهة العملاء')})}
function editGap(key){let [pid,index]=key.split(':'),p=product(pid),field=p.unknown_fields[+index];dialog.innerHTML=`<form method="dialog" class="edit-form"><button class="dialog-close" value="cancel">×</button><span class="eyebrow">إضافة من التاجر</span><h2>${esc(p.name)}</h2><p>المعلومة المطلوبة: ${esc(field)}</p><label>الإجابة التي تعرفها<textarea id="gap-answer" rows="5" placeholder="اكتب المعلومة كما تريد عرضها للعميل"></textarea></label><p class="source-note">ستظهر بوسم «معلومة أضافها التاجر» بعد اعتمادها.</p><div class="modal-actions"><button class="btn primary" id="save-gap" type="button">حفظ واعتماد</button></div></form>`;dialog.showModal();document.querySelector('#save-gap').onclick=()=>{let answer=document.querySelector('#gap-answer').value.trim();if(!answer){toast('اكتب المعلومة قبل الحفظ');return}let f={id:`merchant-${pid}-${E.normalize(String(field))}`,product_id:pid,question:`${field} — ${p.name}`,answer,source:'معلومة أضافها التاجر',category:'المنتجات',status:'approved',merchant:true,count:0};state.faqs=E.merge(state.faqs,[f]);persist();dialog.close();drawDashboard();toast('أضيفت المعلومة وظهرت للعميل')}}
function exportFaqs(){const body=JSON.stringify({store:'رواق القهوة',exported_at:new Date().toISOString(),faqs:listApproved().map(({id,product_id,question,answer,category,source})=>({id,product_id,question,answer,category,source}))},null,2),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type:'application/json'}));a.download='riwaq-approved-faqs.json';a.click();URL.revokeObjectURL(a.href);toast('تم تصدير الأسئلة المعتمدة')}
window.addEventListener('hashchange',nav);window.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();let i=document.querySelector('#product-search,#faq-search,#dash-search');i?.focus()}});nav();
})();
